args:
$ErrorActionPreference='Stop'
if ((Get-Location).ProviderPath -ne 'C:\sgSHIOK2026') { throw 'Wrong cleanup root' }
$profile='C:\sgSHIOK2026\qa\revamp-r1\report-http-20260915\browser-headers-OOLTxs\profile'
$exe='C:\Program Files\Google\Chrome\Application\chrome.exe'
$pattern='(?:^|\s)--user-data-dir="?' + [regex]::Escape($profile) + '(?:"|\s|$)'
$owned=@(Get-CimInstance Win32_Process -Filter "Name='chrome.exe'" | Where-Object { $_.ExecutablePath -ieq $exe -and $_.CommandLine -match $pattern })
$before=@($owned | ForEach-Object { [int]$_.ProcessId })
foreach ($item in $owned) {
  $current=Get-CimInstance Win32_Process -Filter ('ProcessId=' + $item.ProcessId)
  if ($current -and $current.CreationDate -eq $item.CreationDate -and $current.CommandLine -match $pattern) {
    & "$env:SystemRoot\System32\taskkill.exe" /PID $item.ProcessId /T /F | Out-Null
  }
}
$after=@(Get-CimInstance Win32_Process -Filter "Name='chrome.exe'" | Where-Object { $_.ExecutablePath -ieq $exe -and $_.CommandLine -match $pattern } | ForEach-Object { [int]$_.ProcessId })
@{matchedBefore=$before;remaining=$after} | ConvertTo-Json -Compress
